let barcodeLibraryPromise;
function loadBarcodeReader(){if(window.MFDBarcodeReader)return Promise.resolve();if(!barcodeLibraryPromise)barcodeLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/barcode.js';script.onload=resolve;script.onerror=()=>{barcodeLibraryPromise=null;script.remove();reject(Error('Scanner unavailable'))};document.head.appendChild(script)});return barcodeLibraryPromise}
/* Camera barcode scanning plus private, account-owned product photos. */
let barcodeControls=null,barcodeReader=null,barcodeGeneration=0,barcodeBusy=false,photoDraft=[],photoItem=null,photoDraftLoading=false,photoDraftLoadFailed=false,photoDraftPreparing=false;
function stopBarcodeCamera(){barcodeGeneration++;barcodeControls?.stop();barcodeControls=null;let v=$('#barcode-video');if(v?.srcObject){v.srcObject.getTracks().forEach(t=>t.stop());v.srcObject=null}barcodeBusy=false}
barcodePreview=function(){stopBarcodeCamera();modal(modalHead('Scan a barcode')+`<div class="barcode-camera"><video id="barcode-video" muted playsinline></video><div class="barcode-guide" aria-hidden="true"></div></div><div class="camera-actions"><button type="button" class="btn" id="barcode-start" onclick="startBarcodeCamera()">Start camera</button><button type="button" class="btn secondary" onclick="document.getElementById('barcode-photo').click()">Scan a photo</button><button type="button" class="text-btn" onclick="stopBarcodeCamera()">Stop camera</button></div><input type="file" id="barcode-photo" accept="image/*" capture="environment" hidden onchange="scanBarcodePhoto(this.files[0]);this.value='' "><p id="camera-status" class="small-muted" role="status">Use the rear camera and keep the barcode inside the frame.</p><form onsubmit="stopBarcodeCamera();lookupLocalBarcode(event)"><label for="barcode-value">Or enter the barcode</label><input id="barcode-value" required inputmode="numeric" pattern="[0-9]{8,14}" maxlength="14" placeholder="8–14 digits"><div id="barcode-status" role="status"></div><div class="actions"><button type="button" class="btn secondary" onclick="stopBarcodeCamera();renderFoodPicker()">Back</button><button class="btn">Find product</button></div></form>`);$('#modal').classList.add('catalog-modal')};
function cameraMessage(text){let s=$('#camera-status');if(s)s.textContent=text}
async function handleDetectedBarcode(text){if(barcodeBusy||!/^\d{8,14}$/.test(text))return;barcodeBusy=true;stopBarcodeCamera();barcodeBusy=true;let input=$('#barcode-value');if(!input)return;input.value=text;cameraMessage('Barcode found: '+text);await lookupLocalBarcode({preventDefault(){}});barcodeBusy=false}
async function startBarcodeCamera(){stopBarcodeCamera();let generation=barcodeGeneration,video=$('#barcode-video');if(!navigator.mediaDevices?.getUserMedia){cameraMessage('Live camera is unavailable in this browser. Scan a photo or enter the barcode.');return}try{await loadBarcodeReader()}catch{cameraMessage('Scanner unavailable. Enter the barcode.');return}if(generation!==barcodeGeneration||!video?.isConnected)return;cameraMessage('Allow camera access when prompted…');let button=$('#barcode-start');if(button)button.disabled=true;try{barcodeReader=new window.MFDBarcodeReader(undefined,{delayBetweenScanAttempts:250,delayBetweenScanSuccess:1000});let controls=await barcodeReader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}},video,(result,error,controls)=>{if(generation!==barcodeGeneration||!video.isConnected){controls.stop();return}if(result&&/^\d{8,14}$/.test(result.getText())){barcodeControls=controls;handleDetectedBarcode(result.getText())}});if(generation!==barcodeGeneration||!video.isConnected){controls.stop();return}barcodeControls=controls;cameraMessage('Point the camera at the barcode. Keep it steady.')}catch(e){if(generation!==barcodeGeneration)return;cameraMessage(e.name==='NotAllowedError'?'Camera permission was denied. Enable camera access in your browser settings, scan a photo, or enter the barcode.':e.name==='NotFoundError'?'No camera found. Scan a photo or enter the barcode.':'Could not start the camera. Close other camera apps or scan a photo instead.')}finally{if(button?.isConnected)button.disabled=false}}
async function scanBarcodePhoto(file){if(!file)return;stopBarcodeCamera();if(file.size>20*1024*1024){cameraMessage('Choose an image smaller than 20 MB.');return}let url=URL.createObjectURL(file),generation=barcodeGeneration;cameraMessage('Reading barcode from photo…');try{await loadBarcodeReader();if(generation!==barcodeGeneration)return;let reader=new window.MFDBarcodeReader(),result=await reader.decodeFromImageUrl(url);if(generation!==barcodeGeneration)return;let code=result.getText();if(!/^\d{8,14}$/.test(code))throw Error('Unsupported code');await handleDetectedBarcode(code)}catch{if(generation===barcodeGeneration)cameraMessage('No product barcode found. Take a sharper, closer photo or type the digits.')}finally{URL.revokeObjectURL(url)}}
$('#modal').addEventListener('close',stopBarcodeCamera);
new MutationObserver(()=>{if(barcodeControls&&!$('#barcode-video'))stopBarcodeCamera()}).observe($('#modal-content'),{childList:true,subtree:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopBarcodeCamera()});
// Staged photos are resized and stripped of EXIF through canvas before upload.
function clearPhotoDraft(){photoDraft.forEach(p=>{if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url)});photoDraft=[];photoItem=null;photoDraftLoading=false;photoDraftLoadFailed=false}
function photoControls(){return `<section class="product-photo-section"><h3>Product photos</h3><p class="small-muted">Add the nutrition label or packaging. Photos stay private to your account. Enter nutrition values below.</p><div class="camera-actions"><button type="button" class="btn soft" onclick="document.getElementById('label-camera').click()">Take photo</button><button type="button" class="btn secondary" onclick="document.getElementById('label-gallery').click()">Choose images</button></div><input id="label-camera" type="file" accept="image/*" capture="environment" hidden onchange="stageProductPhotos(this.files);this.value=''"><input id="label-gallery" type="file" accept="image/*" multiple hidden onchange="stageProductPhotos(this.files);this.value=''"><div id="label-photo-previews" class="product-photo-grid"></div><p id="label-photo-status" class="small-muted" role="status">Up to four photos. Saved with the product.</p></section>`}
const cameraNewLabel=newLabelProduct;newLabelProduct=function(barcode=''){clearPhotoDraft();cameraNewLabel(barcode);let form=$('#modal-content form');form.insertAdjacentHTML('afterbegin',photoControls())};
async function resizeProductPhoto(file){if(!file.type.startsWith('image/'))throw Error('Choose an image file.');if(file.size>20*1024*1024)throw Error('Choose an image smaller than 20 MB.');let url=URL.createObjectURL(file);try{let img=new Image();img.src=url;await img.decode();let scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));let context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob||blob.size>2*1024*1024)throw Error('Image is too large. Choose a smaller image.');return blob}catch(e){throw Error(e.message||'Image could not be opened. Try a JPEG or PNG.')}finally{URL.revokeObjectURL(url)}}
async function stageProductPhotos(files){let status=$('#label-photo-status');if(photoDraftLoading||photoDraftLoadFailed){if(status)status.textContent='Reopen the product once its saved photos are available.';return}if(status)status.textContent='Preparing photos…';photoDraftPreparing=true;let target=$('#label-photo-previews'),draft=photoDraft;try{for(let file of Array.from(files)){if(draft.length>=4)throw Error('Maximum four photos per product.');let blob=await resizeProductPhoto(file);if(target!==$('#label-photo-previews')||draft!==photoDraft)return;draft.push({blob,url:URL.createObjectURL(blob)})}paintProductPhotos();if(status?.isConnected)status.textContent='Photos ready. Save the product to upload them.'}catch(e){if(status?.isConnected)status.textContent=e.message;paintProductPhotos()}finally{photoDraftPreparing=false}}
function paintProductPhotos(){let target=$('#label-photo-previews');if(target)target.innerHTML=photoDraft.map((p,i)=>`<div><a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Product photo ${i+1}"></a><button type="button" class="text-btn" onclick="removeProductPhoto(${i})">Remove</button></div>`).join('')}
function removeProductPhoto(i){let p=photoDraft[i];if(p?.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);photoDraft.splice(i,1);paintProductPhotos()}
async function getPrivateProductPhotos(id){let {data,error}=await cloud.client.from('mfd_catalogue_photos').select('id,path').eq('item_id',id).order('created_at');if(error)throw error;let photos=[];for(let p of data){let {data:signed,error}=await cloud.client.storage.from('catalogue-photos').createSignedUrl(p.path,600);if(error)throw error;photos.push({...p,url:signed.signedUrl})}return photos}
const cameraEditItem=editSharedItem;editSharedItem=async function(id){await cameraEditItem(id);let row=sharedRow(id);if(!row||row.kind!=='food'||!sharedIsOwner(row))return;photoItem=id;photoDraftLoading=true;let target=$('#label-photo-previews');try{let photos=await getPrivateProductPhotos(id);if(target!==$('#label-photo-previews'))return;photoDraft=photos;photoDraftLoading=false;paintProductPhotos()}catch(e){photoDraftLoading=false;photoDraftLoadFailed=true;if($('#label-photo-status'))$('#label-photo-status').textContent='Could not load saved photos. '+sharedErrorText(e)}};
const cameraSaveRecord=saveSharedRecord;saveSharedRecord=async function(kind,name,barcode,data,id=null){if(kind!=='food')return cameraSaveRecord(kind,name,barcode,data,id);if(photoDraftPreparing)throw Error('Wait for photos to finish preparing.');if(photoDraftLoading||photoDraftLoadFailed)throw Error('Saved photos could not be loaded yet. Reopen the product before saving.');let draft=photoDraft.slice(),account=cloud.user?.id,row=await cameraSaveRecord(kind,name,barcode,data,id);sharedEditId=row.id;try{let existing=await cloud.client.from('mfd_catalogue_photos').select('id,path').eq('item_id',row.id);if(existing.error)throw existing.error;for(let p of draft.filter(p=>p.blob)){if(cloud.user?.id!==account)throw Error('Account changed.');let path=account+'/'+crypto.randomUUID()+'.jpg',upload=await cloud.client.storage.from('catalogue-photos').upload(path,p.blob,{contentType:'image/jpeg',upsert:false});if(upload.error)throw upload.error;let meta=await cloud.client.from('mfd_catalogue_photos').insert({item_id:row.id,path}).select('id').single();if(meta.error){await cloud.client.storage.from('catalogue-photos').remove([path]);throw meta.error}p.path=path;p.id=meta.data.id;delete p.blob;let original=photoDraft.find(x=>x.url===p.url);if(original)Object.assign(original,p),delete original.blob}let keep=new Set(draft.map(p=>p.path).filter(Boolean));for(let p of existing.data.filter(p=>!keep.has(p.path))){let removed=await cloud.client.storage.from('catalogue-photos').remove([p.path]);if(removed.error)throw removed.error;let deleted=await cloud.client.from('mfd_catalogue_photos').delete().eq('id',p.id);if(deleted.error)throw deleted.error}clearPhotoDraft();return row}catch(e){throw Error('Product saved, but photos need attention: '+sharedErrorText(e)+'. Keep this form open and save again to retry.')}};
const cameraPortion=portionModal;portionModal=function(product,edit=null){cameraPortion(product,edit);if(!product.sharedId)return;let row=sharedRow(product.sharedId);if(!sharedIsOwner(row))return;let target=document.createElement('section');target.className='product-photo-section';target.innerHTML='<h3>Your product photos</h3><div class="product-photo-grid"></div>';$('#modal-content').append(target);getPrivateProductPhotos(row.id).then(photos=>{if(!target.isConnected)return;target.querySelector('div').innerHTML=photos.map((p,i)=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Product photo ${i+1}"></a>`).join('');if(!photos.length)target.remove()}).catch(()=>{if(target.isConnected)target.innerHTML='<p class="small-muted">Photos unavailable. Reopen the product to retry.</p>'})};
const cameraFoodPicker=renderFoodPicker;renderFoodPicker=function(){cameraFoodPicker();let button=$('#modal-content .food-search-row button[onclick="barcodePreview()"]');if(button){button.innerHTML='<span aria-hidden="true">▥</span> Scan';button.classList.add('scan-barcode-button');button.setAttribute('aria-label','Scan barcode with camera')}};
